-- Vidya Loop: sample data for the SQL Path project "Marketing funnel analysis".
-- A fictional Indian online-learning company selling data and coding courses. Twelve weeks of
-- website sessions (2025-01-06 to 2025-03-30), funnel events, orders and campaign spend.
-- Synthetic data, generated by a fixed-seed script. Amounts are whole Indian rupees.
-- Things to watch: sessions with no campaign are organic or direct visits; some events were logged
-- twice; a few purchases lost their checkout event; the checkout A/B test started on 2025-02-17.

CREATE TABLE campaigns (
  campaign_id INTEGER PRIMARY KEY,
  name        TEXT    NOT NULL,
  channel     TEXT    NOT NULL,
  spend       INTEGER NOT NULL
);


CREATE TABLE courses (
  course_id INTEGER PRIMARY KEY,
  name      TEXT    NOT NULL,
  price     INTEGER NOT NULL
);


-- One row per visit. campaign_id is NULL for organic and direct visits. variant is the checkout
-- A/B test group ('A' = current page, 'B' = new page), set only from 2025-02-17.
CREATE TABLE sessions (
  session_id   INTEGER PRIMARY KEY,
  visitor_id   INTEGER NOT NULL,
  session_date TEXT    NOT NULL,
  campaign_id  INTEGER REFERENCES campaigns (campaign_id),
  device       TEXT    NOT NULL,
  variant      TEXT
);


-- One row per funnel step reached in a session: 'view_course', 'signup', 'start_trial', 'checkout', 'purchase'.
CREATE TABLE events (
  session_id INTEGER NOT NULL REFERENCES sessions (session_id),
  step       TEXT    NOT NULL
);


-- One row per course purchase. Revenue = price - discount.
CREATE TABLE orders (
  order_id   INTEGER PRIMARY KEY,
  session_id INTEGER NOT NULL REFERENCES sessions (session_id),
  visitor_id INTEGER NOT NULL,
  course_id  INTEGER NOT NULL REFERENCES courses (course_id),
  price      INTEGER NOT NULL,
  discount   INTEGER NOT NULL
);

